  const li = (t, s, type, arg, cls, right) => `<button type="button" class="m3d-li${cls ? ' ' + cls : ''}" data-m3d="${esc(type)}" data-arg="${esc(arg == null ? '' : arg)}"><span class="tx"><b>${t}</b>${s ? `<small>${s}</small>` : ''}</span>${right || ''}</button>`;
  const chip = (t, cls) => `<span class="m3d-tag ${cls || ''}">${t}</span>`;
