  function depotCard(d) { const M = d.people || []; const here = M.filter(p => p.today && p.today.where === 'depot').length, onCh = M.filter(p => p.today && p.today.where === 'chantier').length; const V2 = d.vehicles || []; const al = V2.reduce((a, v) => a + (v.alerts || []).filter(x => x.sev === 'bad').length, 0); const st = d.stock || {};
    return card(esc(d.nom) + (d.ville ? ' · ' + esc(d.ville) : ''), `<div class="m3d-kpis"><div><b>${M.length}</b><small>personnes</small></div><div><b>${here}</b><small>au dépôt</small></div><div><b>${onCh}</b><small>sur chantier</small></div><div><b style="color:${al ? '#A3221F' : '#0E6B5C'}">${V2.length}</b><small>véhicules${al ? ' · ' + al + ' alerte' + (al > 1 ? 's' : '') : ''}</small></div></div>
      <div class="m3d-btns">${btn('🪑 Bureaux', 'cam', 'bureaux')}${btn('📦 Magasin', 'cam', 'magasin')}${btn('🚐 Parking', 'cam', 'parking')}${btn('🛋 Accueil', 'cam', 'attente')}${btn('⟲ Tout le dépôt', 'cam', 'all')}</div>
      ${st.n ? `<div class="hint" style="margin-top:6px">Magasin : ${st.n} articles${st.bas ? ' · <b style="color:#C08A2E">' + st.bas + ' à commander</b>' : ''}${st.rup ? ' · <b style="color:#A3221F">' + st.rup + ' en rupture</b>' : ''}</div>` : ''}`); }
  function peopleList(d, filter) { const L = (d.people || []).filter(filter || (() => true)); return L.map(p => li(esc(p.prenom) + (p.nom ? ' ' + esc(p.nom) : ''), esc(p.posteLabel || '') + (p.today && p.today.where === 'chantier' ? ' · 🦺 ' + esc(p.today.chantierNom || '') : p.today && p.today.where === 'depot' ? ' · au dépôt' : ''), 'person', p.id, H.sel && H.sel.type === 'person' && H.sel.id === p.id ? 'on' : '')).join('') || '<div class="hint">—</div>'; }
  function bindActs(root) { root.querySelectorAll('[data-m3d]').forEach(b => b.onclick = e => { e.stopPropagation(); const t = b.dataset.m3d, a = b.dataset.arg; handle(t, a); }); root.querySelectorAll('[data-m3dinput]').forEach(i => i.onchange = () => { const [k, num] = i.dataset.m3dinput.split('|'); act('attente_field', num, { k, v: i.value }); }); }
  function setSide(html) { side.innerHTML = html; bindActs(side); }
